select
    DTQ.DTQ_VIAGEM,
    DT6.DT6_FILVGA,
    DT6.DT6_NUMVGA,
    DT6.DT6_DOC,
    DT6.DT6_SERIE,
    convert(date, DT6.DT6_DATEMI, 103) as DT6_DATEMI, 
    DT6.DT6_VALFRE as CTE_TOTAL,
    DT6.DT6_VALIMP as IMPOSTO_TOTAL,
    DT6.DT6_VALTOT,
    DT6.DT6_CLIDEV,
    DT6.DT6_LOJDEV,
    SD2.D2_DOC,
    SD2.D2_SERIE

from DT6010 DT6
    left join DTQ010 DTQ (nolock)
        on DTQ.D_E_L_E_T_ = ''
        and DTQ.DTQ_FILORI = DT6.DT6_FILVGA
        and DTQ.DTQ_VIAGEM = DT6.DT6_NUMVGA
    left join SD2010 SD2 (nolock)
        on SD2.D_E_L_E_T_ = ''
        and SD2.D2_NFORI = DT6.DT6_DOC
        and SD2.D2_SERIORI = DT6.DT6_SERIE
        and SD2.D2_CLIENTE = DT6.DT6_CLIDEV
        and SD2.D2_LOJA = DT6.DT6_LOJDEV
where
        DT6.D_E_L_E_T_ = ''
    and DT6.DT6_DOC in ('000001191','000001192','000001193','000001194','000001196','000001197','000001198','000001202','000001203','000001204','000001205','000001206','000001207','000001208','000001209','000001219','000000261','000000262','000050723','000001240','000001241','000001242','000001243','000001244','000001245','000050771','000001963','000001279','000001280','000001281','000001282','000001283','000000263','000000264','000001293','000001294','000001295','000001296','000001297','000001298','000001299','000001300','000001301','000001302','000001303','000001304','000001305','000001306','000001307','000001308','000001309','000001310','000001311','000001312','000000265','000001313','000001314','000001315','000001316','000001317','000001318','000001319','000001320','000001321','000001322','000001323','000001324','000001325','000001326','000001327','000001328','000001329','000001330','000001331','000001332','000001333','000001334','000001335','000001336','000001337','000001338','000001339','000001340','000001341','000001342','000001343','000001344','000001345','000001346','000001347','000001348','000001349','000001350','000001351','000001352','000001353','000001354','000001355','000001356','000001357','000001358','000001359','000001360','000001361','000001362','000001363','000001364','000001365','000001366','000001367','000001368','000001369','000001370','000001371','000001372','000001373','000001374','000001375','000001376','000001378','000001379','000001380','000001381','000001382','000001383','000001384','000001385','000001386','000001387','000001388','000001389','000001390','000001391','000001392','000001393','000001394','000001395','000001396','000001397','000001398','000001399','000001400','000001401','000001402','000001403','000001404','000001405','000001406','000050923','000001407','000001408','000050957','000050958','000050959','000050960','000050991','000001455','000001456','000001457','000001458','000001459','000001462','000001463','000001464','0000014